"use client";

import { createRouterTransport, type Transport } from "@connectrpc/connect";
import { TransportProvider } from "@connectrpc/connect-query";
import { QueryClient, QueryClientProvider } from "@tanstack/react-query";
import { useState } from "react";

import { LibraryService } from "@/registry/base-nova/protoform/demo/runtime/gen/protoform/conformance/v1/aip_pb";

import { BookstoreWorkspace } from "./bookstore-workspace";
import { createLibraryService } from "./library-service";

export const client = "only";

interface BookstoreDemoProps {
  transport?: Transport;
  visitorId?: string;
}

const VISITOR_KEY = "protoform-bookstore-visitor";

function newVisitorId(): string {
  return `demo-${globalThis.crypto.randomUUID().toLowerCase()}`;
}

function initialVisitorId(provided?: string): string {
  if (provided) {
    return provided;
  }
  if (typeof sessionStorage === "undefined") {
    return newVisitorId();
  }
  const stored = sessionStorage.getItem(VISITOR_KEY);
  if (stored) {
    return stored;
  }
  const created = newVisitorId();
  sessionStorage.setItem(VISITOR_KEY, created);
  return created;
}

export function BookstoreDemo({ transport: providedTransport, visitorId: providedVisitorId }: BookstoreDemoProps) {
  const [queryClient] = useState(() => new QueryClient());
  const [transport] = useState(
    () => providedTransport ?? createRouterTransport((router) => router.service(LibraryService, createLibraryService()))
  );
  const [visitorId, setVisitorId] = useState(() => initialVisitorId(providedVisitorId));

  function resetLibrary() {
    const next = newVisitorId();
    if (typeof sessionStorage !== "undefined") {
      sessionStorage.setItem(VISITOR_KEY, next);
    }
    queryClient.clear();
    setVisitorId(next);
  }

  return (
    <TransportProvider transport={transport}>
      <QueryClientProvider client={queryClient}>
        <BookstoreWorkspace onReset={resetLibrary} parent={`publishers/${visitorId}`} />
      </QueryClientProvider>
    </TransportProvider>
  );
}

export default BookstoreDemo;

"use client";

import { skipToken, useQuery } from "@connectrpc/connect-query";
import { type ReactNode, useState } from "react";
import { Alert, AlertDescription, AlertTitle } from "@/components/ui/alert";
import { Badge } from "@/components/ui/badge";
import { Button } from "@/components/ui/button";
import { Card, CardContent, CardDescription, CardHeader, CardTitle } from "@/components/ui/card";
import { Field, FieldLabel } from "@/components/ui/field";
import { Input } from "@/components/ui/input";
import { LibraryService } from "@/registry/base-nova/protoform/demo/runtime/gen/protoform/conformance/v1/aip_pb";
import { BookDetail } from "./book-detail";
import { CreateBookForm } from "./create-book-form";
import { DeleteBookForm } from "./delete-book-form";
import { UpdateBookForm } from "./update-book-form";

type View = "create" | "delete" | "detail" | "edit" | "list";

export function BookstoreWorkspace({ onReset, parent }: { onReset: () => void; parent: string }) {
  const [view, setView] = useState<View>("list");
  const [selectedName, setSelectedName] = useState<string>();
  const [filter, setFilter] = useState("");
  const list = useQuery(LibraryService.method.listBooks, { filter, parent });
  const detail = useQuery(LibraryService.method.getBook, selectedName ? { name: selectedName } : skipToken);

  function openBook(name: string) {
    setSelectedName(name);
    setView("detail");
  }

  function returnToList() {
    setSelectedName(undefined);
    setView("list");
  }

  function resetLibrary() {
    returnToList();
    setFilter("");
    onReset();
  }

  function handleDeleted() {
    returnToList();
    return list.refetch();
  }

  const selected = detail.data;
  let listContent: ReactNode;
  if (list.isPending) {
    listContent = <p aria-live="polite">Loading books…</p>;
  } else if (list.error) {
    listContent = (
      <Alert variant="destructive">
        <AlertTitle>Books not loaded</AlertTitle>
        <AlertDescription className="gap-3">
          {list.error.message}
          <Button onClick={() => list.refetch()} type="button" variant="outline">
            Retry
          </Button>
        </AlertDescription>
      </Alert>
    );
  } else if (list.data.books.length === 0) {
    listContent = (
      <p className="rounded-lg border border-dashed p-6 text-muted-foreground text-sm">No books match this filter.</p>
    );
  } else {
    listContent = (
      <div className="grid gap-3 sm:grid-cols-2">
        {list.data.books.map((book) => (
          <Card key={book.name} size="full" variant="outlined">
            <CardHeader>
              <CardTitle level={3}>
                <Button
                  className="h-auto justify-start whitespace-normal p-0 text-left text-lg"
                  onClick={() => openBook(book.name)}
                  type="button"
                  variant="link"
                >
                  {book.displayName}
                </Button>
              </CardTitle>
              <CardDescription>{book.isbn}</CardDescription>
            </CardHeader>
            <CardContent>
              <p className="line-clamp-2 text-muted-foreground text-sm">{book.note || "No note yet."}</p>
            </CardContent>
          </Card>
        ))}
      </div>
    );
  }

  return (
    <div className="w-full space-y-6 rounded-xl border bg-background p-4 sm:p-6">
      <header className="flex flex-col justify-between gap-4 border-b pb-5 sm:flex-row sm:items-start">
        <div className="space-y-2">
          <div className="flex flex-wrap gap-2">
            <Badge variant="outline">5 RPCs</Badge>
            <Badge variant="outline">Generated bindings</Badge>
            <Badge variant="outline">Visitor-isolated state</Badge>
          </div>
          <h1 className="font-semibold text-3xl">Protoform library</h1>
          <p className="max-w-2xl text-muted-foreground text-sm">
            Create with an RHF stepper, edit with a field mask and etag, and confirm deletion through AutoForm.
          </p>
        </div>
        <Button onClick={resetLibrary} type="button" variant="outline">
          Reset demo
        </Button>
      </header>

      {view === "list" ? (
        <section aria-labelledby="book-list-title" className="space-y-5">
          <div className="flex flex-col justify-between gap-4 sm:flex-row sm:items-end">
            <div>
              <h2 className="font-semibold text-2xl" id="book-list-title">
                Books
              </h2>
              <p className="text-muted-foreground text-sm">Live ListBooks results from your temporary library.</p>
            </div>
            <Button onClick={() => setView("create")} type="button">
              Create book
            </Button>
          </div>
          <Field className="max-w-md">
            <FieldLabel htmlFor="book-filter">Filter books</FieldLabel>
            <Input
              id="book-filter"
              onChange={(event) => setFilter(event.target.value)}
              placeholder="Title or ISBN"
              type="search"
              value={filter}
            />
          </Field>
          {listContent}
        </section>
      ) : null}

      {view === "create" ? (
        <CreateBookForm onCancel={returnToList} onCreated={(name) => openBook(name)} parent={parent} />
      ) : null}

      {view === "detail" ? (
        <BookDetail
          book={selected}
          error={detail.error?.message}
          isPending={detail.isPending}
          onBack={returnToList}
          onDelete={() => setView("delete")}
          onEdit={() => setView("edit")}
          onRetry={() => detail.refetch()}
        />
      ) : null}

      {view === "edit" && selected ? (
        <UpdateBookForm book={selected} onCancel={() => setView("detail")} onUpdated={() => setView("detail")} />
      ) : null}

      {view === "delete" && selected ? (
        <DeleteBookForm book={selected} onCancel={() => setView("detail")} onDeleted={handleDeleted} />
      ) : null}
    </div>
  );
}

"use client";

import { Alert, AlertDescription, AlertTitle } from "@/components/ui/alert";
import { Button } from "@/components/ui/button";
import type { Book } from "@/registry/base-nova/protoform/demo/runtime/gen/protoform/conformance/v1/aip_pb";

export function BookDetail({
  book,
  error,
  isPending,
  onBack,
  onDelete,
  onEdit,
  onRetry,
}: {
  book?: Book | undefined;
  error?: string | undefined;
  isPending: boolean;
  onBack: () => void;
  onDelete: () => void;
  onEdit: () => void;
  onRetry: () => void;
}) {
  if (isPending) {
    return <p aria-live="polite">Loading book…</p>;
  }
  if (error || !book) {
    return (
      <Alert variant="destructive">
        <AlertTitle>Book not loaded</AlertTitle>
        <AlertDescription className="gap-3">
          {error ?? "The book no longer exists."}
          <Button onClick={onRetry} type="button" variant="outline">
            Retry
          </Button>
        </AlertDescription>
      </Alert>
    );
  }

  return (
    <section aria-labelledby="book-detail-title" className="space-y-6">
      <Button onClick={onBack} type="button" variant="ghost">
        Back to books
      </Button>
      <div className="space-y-2">
        <h2 className="font-semibold text-3xl" id="book-detail-title">
          {book.displayName}
        </h2>
        <p className="font-mono text-muted-foreground text-sm">{book.isbn}</p>
        <p className="text-sm">{book.note || "No note yet."}</p>
      </div>
      <dl className="grid gap-3 rounded-lg border p-4 text-sm sm:grid-cols-2">
        <div>
          <dt className="text-muted-foreground">Resource name</dt>
          <dd className="break-all font-mono">{book.name}</dd>
        </div>
        <div>
          <dt className="text-muted-foreground">Etag</dt>
          <dd className="font-mono">{book.etag}</dd>
        </div>
      </dl>
      <div className="flex flex-wrap gap-3">
        <Button onClick={onEdit} type="button">
          Edit book
        </Button>
        <Button onClick={onDelete} type="button" variant="destructive-outline">
          Delete book
        </Button>
      </div>
    </section>
  );
}

"use client";

import { create } from "@bufbuild/protobuf";
import { createConnectQueryKey, useMutation, useTransport } from "@connectrpc/connect-query";
import { useQueryClient } from "@tanstack/react-query";
import { useState } from "react";

import { Alert, AlertDescription, AlertTitle } from "@/components/ui/alert";
import { Button } from "@/components/ui/button";
import { Field, FieldDescription, FieldError, FieldLabel } from "@/components/ui/field";
import { Input } from "@/components/ui/input";
import { Textarea } from "@/components/ui/textarea";
import { BookFormBinding } from "@/registry/base-nova/protoform/demo/runtime/gen/protoform/conformance/v1/aip_form";
import {
  BookSchema,
  LibraryService,
} from "@/registry/base-nova/protoform/demo/runtime/gen/protoform/conformance/v1/aip_pb";
import { useProtoForm } from "@/registry/base-nova/protoform/hooks/use-proto-form";

interface CreateBookFormProps {
  onCancel: () => void;
  onCreated: (name: string) => void;
  parent: string;
}

const bookIdInputPattern = String.raw`[a-z][a-z0-9\-]{2,62}[a-z0-9]`;
const BOOK_ID_PATTERN = /^[a-z][a-z0-9-]{2,62}[a-z0-9]$/u;

export function CreateBookForm({ onCancel, onCreated, parent }: CreateBookFormProps) {
  const [step, setStep] = useState<"book" | "publishing">("book");
  const [bookId, setBookId] = useState("");
  const queryClient = useQueryClient();
  const transport = useTransport();
  const mutation = useMutation(LibraryService.method.createBook);
  const form = useProtoForm(BookFormBinding.descriptor, {
    defaultValues: create(BookSchema, { displayName: "", isbn: "", note: "" }),
    mode: "onChange",
    serverPathPrefix: "book",
  });

  async function continueToPublishing() {
    const valid = await form.trigger(["displayName", "isbn"]);
    if (valid) {
      setStep("publishing");
    }
  }

  async function submitBook() {
    if (!BOOK_ID_PATTERN.test(bookId)) {
      return;
    }
    form.clearServerErrorContext();
    try {
      const response = await mutation.mutateAsync({
        book: form.createMessage(),
        bookId,
        parent,
      });
      await queryClient.invalidateQueries({
        queryKey: createConnectQueryKey({
          cardinality: undefined,
          input: { parent },
          schema: LibraryService.method.listBooks,
          transport,
        }),
      });
      onCreated(response.name);
    } catch (error) {
      form.setServerErrors(error);
    }
  }

  const titleError = form.formState.errors.displayName?.message;
  const isbnError = form.formState.errors.isbn?.message;
  const bookIdInvalid = bookId.length > 0 && !BOOK_ID_PATTERN.test(bookId);
  const {
    name: displayName,
    onBlur: handleDisplayNameBlur,
    onChange: handleDisplayNameChange,
    ref: displayNameRef,
  } = form.register("displayName");
  const { name: isbn, onBlur: handleIsbnBlur, onChange: handleIsbnChange, ref: isbnRef } = form.register("isbn");
  const { name: note, onBlur: handleNoteBlur, onChange: handleNoteChange, ref: noteRef } = form.register("note");

  return (
    <section aria-labelledby="create-book-title" className="space-y-6">
      <div className="space-y-2">
        <p className="font-medium text-muted-foreground text-sm">Step {step === "book" ? "1" : "2"} of 2</p>
        <h2 className="font-semibold text-2xl" id="create-book-title">
          Create a book
        </h2>
        <p className="text-muted-foreground text-sm">
          React Hook Form state, generated Protoform binding, and protobuf CEL validation.
        </p>
      </div>

      {step === "book" ? (
        <div className="space-y-5">
          <Field data-invalid={Boolean(titleError)}>
            <FieldLabel htmlFor="create-book-title-input">Title</FieldLabel>
            <Input
              aria-invalid={Boolean(titleError)}
              id="create-book-title-input"
              name={displayName}
              onBlur={handleDisplayNameBlur}
              onChange={handleDisplayNameChange}
              ref={displayNameRef}
            />
            {titleError ? <FieldError>{titleError}</FieldError> : null}
          </Field>
          <Field data-invalid={Boolean(isbnError)}>
            <FieldLabel htmlFor="create-book-isbn">ISBN-13</FieldLabel>
            <Input
              aria-describedby={isbnError ? undefined : "create-book-isbn-help"}
              aria-invalid={Boolean(isbnError)}
              id="create-book-isbn"
              inputMode="numeric"
              name={isbn}
              onBlur={handleIsbnBlur}
              onChange={handleIsbnChange}
              placeholder="9783161484100"
              ref={isbnRef}
            />
            {isbnError ? (
              <FieldError>{isbnError}</FieldError>
            ) : (
              <FieldDescription id="create-book-isbn-help">
                Thirteen digits. The check digit is verified by the CEL rule in the proto.
              </FieldDescription>
            )}
          </Field>
          <div className="flex flex-wrap justify-between gap-3">
            <Button onClick={onCancel} type="button" variant="outline">
              Cancel
            </Button>
            <Button onClick={continueToPublishing} type="button">
              Continue
            </Button>
          </div>
        </div>
      ) : (
        <form className="space-y-5" onSubmit={form.handleSubmit(submitBook)}>
          <Field data-invalid={bookIdInvalid}>
            <FieldLabel htmlFor="create-book-id">Book id</FieldLabel>
            <Input
              aria-invalid={bookIdInvalid}
              id="create-book-id"
              onChange={(event) => setBookId(event.target.value)}
              pattern={bookIdInputPattern}
              required
              value={bookId}
            />
            {bookIdInvalid ? <FieldError>Use lowercase letters, numbers, and hyphens.</FieldError> : null}
          </Field>
          <Field>
            <FieldLabel htmlFor="create-book-note">Note</FieldLabel>
            <Textarea
              id="create-book-note"
              name={note}
              onBlur={handleNoteBlur}
              onChange={handleNoteChange}
              ref={noteRef}
            />
          </Field>
          {mutation.error ? (
            <Alert variant="destructive">
              <AlertTitle>Book not created</AlertTitle>
              <AlertDescription>{mutation.error.message}</AlertDescription>
            </Alert>
          ) : null}
          <div className="flex flex-wrap justify-between gap-3">
            <Button onClick={() => setStep("book")} type="button" variant="outline">
              Back
            </Button>
            <Button disabled={bookIdInvalid || bookId.length === 0} isLoading={mutation.isPending} type="submit">
              Create book
            </Button>
          </div>
        </form>
      )}
    </section>
  );
}

"use client";

import { createConnectQueryKey, useMutation, useTransport } from "@connectrpc/connect-query";
import { useQueryClient } from "@tanstack/react-query";
import { useState } from "react";
import { Alert, AlertDescription, AlertTitle } from "@/components/ui/alert";
import { Button } from "@/components/ui/button";
import { Field, FieldError, FieldLabel } from "@/components/ui/field";
import { Input } from "@/components/ui/input";
import { Textarea } from "@/components/ui/textarea";
import { BookFormBinding } from "@/registry/base-nova/protoform/demo/runtime/gen/protoform/conformance/v1/aip_form";
import type { Book } from "@/registry/base-nova/protoform/demo/runtime/gen/protoform/conformance/v1/aip_pb";
import { LibraryService } from "@/registry/base-nova/protoform/demo/runtime/gen/protoform/conformance/v1/aip_pb";
import { useProtoForm } from "@/registry/base-nova/protoform/hooks/use-proto-form";

interface UpdateBookFormProps {
  book: Book;
  onCancel: () => void;
  onUpdated: () => void;
}

export function UpdateBookForm({ book, onCancel, onUpdated }: UpdateBookFormProps) {
  const queryClient = useQueryClient();
  const transport = useTransport();
  const mutation = useMutation(LibraryService.method.updateBook);
  const [formError, setFormError] = useState<string>();
  const form = useProtoForm(BookFormBinding.descriptor, {
    defaultValues: book,
    mode: "onChange",
    serverPathPrefix: "book",
  });

  function handleInvalid(errors: typeof form.formState.errors) {
    setFormError(`Review these fields: ${Object.keys(errors).join(", ")}.`);
  }

  async function saveChanges() {
    setFormError(undefined);
    const valid = await form.trigger(["displayName", "note"]);
    if (!valid) {
      handleInvalid(form.formState.errors);
      return;
    }
    await submitUpdate();
  }

  async function submitUpdate() {
    setFormError(undefined);
    form.clearServerErrorContext();
    const updateMask = form.createUpdateMask();
    if (updateMask.paths.length === 0) {
      setFormError("Change the title or note before saving.");
      return;
    }
    try {
      const response = await mutation.mutateAsync({
        book: form.createMessage(),
        updateMask,
      });
      queryClient.setQueryData(
        createConnectQueryKey({
          cardinality: "finite",
          input: { name: response.name },
          schema: LibraryService.method.getBook,
          transport,
        }),
        response
      );
      const parent = response.name.split("/books/")[0] ?? "";
      await queryClient.invalidateQueries({
        queryKey: createConnectQueryKey({
          cardinality: undefined,
          input: { parent },
          schema: LibraryService.method.listBooks,
          transport,
        }),
      });
      onUpdated();
    } catch (error) {
      form.setServerErrors(error);
    }
  }

  const titleError = form.formState.errors.displayName?.message;
  const {
    name: displayName,
    onBlur: handleDisplayNameBlur,
    onChange: handleDisplayNameChange,
    ref: displayNameRef,
  } = form.register("displayName");
  const { name: note, onBlur: handleNoteBlur, onChange: handleNoteChange, ref: noteRef } = form.register("note");
  return (
    <section aria-labelledby="edit-book-title" className="space-y-6">
      <div className="space-y-2">
        <h2 className="font-semibold text-2xl" id="edit-book-title">
          Edit book
        </h2>
        <p className="text-muted-foreground text-sm">
          Protoform derives the update mask. The service checks the book etag.
        </p>
      </div>
      <form className="space-y-5" onSubmit={form.handleSubmit(submitUpdate, handleInvalid)}>
        <Field data-invalid={Boolean(titleError)}>
          <FieldLabel htmlFor="update-book-title">Title</FieldLabel>
          <Input
            aria-invalid={Boolean(titleError)}
            id="update-book-title"
            name={displayName}
            onBlur={handleDisplayNameBlur}
            onChange={handleDisplayNameChange}
            ref={displayNameRef}
          />
          {titleError ? <FieldError>{titleError}</FieldError> : null}
        </Field>
        <Field>
          <FieldLabel htmlFor="update-book-note">Note</FieldLabel>
          <Textarea
            id="update-book-note"
            name={note}
            onBlur={handleNoteBlur}
            onChange={handleNoteChange}
            ref={noteRef}
          />
        </Field>
        {formError || mutation.error ? (
          <Alert variant="destructive">
            <AlertTitle>Changes not saved</AlertTitle>
            <AlertDescription>{formError ?? mutation.error?.message}</AlertDescription>
          </Alert>
        ) : null}
        <div className="flex flex-wrap justify-between gap-3">
          <Button onClick={onCancel} type="button" variant="outline">
            Cancel
          </Button>
          <Button isLoading={mutation.isPending} onClick={saveChanges} type="button">
            Save changes
          </Button>
        </div>
      </form>
    </section>
  );
}

"use client";

import { create } from "@bufbuild/protobuf";
import { useMutation } from "@connectrpc/connect-query";
import { Button } from "@/components/ui/button";
import { AutoForm } from "@/registry/base-nova/protoform/components/auto-form";
import { DeleteBookRequestFormBinding } from "@/registry/base-nova/protoform/demo/runtime/gen/protoform/conformance/v1/aip_form";
import type { Book } from "@/registry/base-nova/protoform/demo/runtime/gen/protoform/conformance/v1/aip_pb";
import {
  DeleteBookRequestSchema,
  LibraryService,
} from "@/registry/base-nova/protoform/demo/runtime/gen/protoform/conformance/v1/aip_pb";
import { DeleteSubmitButton } from "./delete-submit-button";

interface DeleteBookFormProps {
  book: Book;
  onCancel: () => void;
  onDeleted: () => void;
}

const deleteUiComponents = { SubmitButton: DeleteSubmitButton };

export function DeleteBookForm({ book, onCancel, onDeleted }: DeleteBookFormProps) {
  const mutation = useMutation(LibraryService.method.deleteBook);

  async function deleteBook() {
    await mutation.mutateAsync({ etag: book.etag, name: book.name });
    onDeleted();
  }

  return (
    <section aria-labelledby="delete-book-title" className="space-y-6">
      <div className="space-y-2">
        <h2 className="font-semibold text-2xl" id="delete-book-title">
          Delete book
        </h2>
        <p className="text-muted-foreground text-sm">
          Delete <strong>{book.displayName}</strong>? AutoForm renders the generated delete request; app-owned copy
          provides the confirmation.
        </p>
      </div>
      <AutoForm
        defaultValues={create(DeleteBookRequestSchema, {
          etag: book.etag,
          name: book.name,
        })}
        fieldConfig={{
          etag: { customData: { hidden: true } },
          name: { customData: { hidden: true } },
          requestId: { customData: { hidden: true } },
          validateOnly: { customData: { hidden: true } },
        }}
        onSubmit={deleteBook}
        schema={DeleteBookRequestFormBinding.descriptor}
        uiComponents={deleteUiComponents}
        withSubmit
      />
      <Button onClick={onCancel} type="button" variant="outline">
        Cancel
      </Button>
      {mutation.error ? <p className="text-destructive text-sm">{mutation.error.message}</p> : null}
    </section>
  );
}

import type { ReactNode } from "react";
import { Button } from "@/components/ui/button";

export function DeleteSubmitButton({
  disabled,
  testId,
}: {
  children: ReactNode;
  disabled?: boolean | undefined;
  testId?: string | undefined;
}) {
  return (
    <Button disabled={disabled} testId={testId} type="submit" variant="destructive">
      {disabled ? "Deleting…" : "Delete book"}
    </Button>
  );
}

import { BadRequestSchema } from "@buf/googleapis_googleapis.bufbuild_es/google/rpc/error_details_pb.js";
import { clone, create } from "@bufbuild/protobuf";
import { EmptySchema, timestampFromDate, timestampMs } from "@bufbuild/protobuf/wkt";
import { Code, ConnectError, type ServiceImpl } from "@connectrpc/connect";

import {
  type Book,
  BookSchema,
  BookState,
  type LibraryService,
} from "@/registry/base-nova/protoform/demo/runtime/gen/protoform/conformance/v1/aip_pb";

const PARENT_PATTERN = /^publishers\/[a-z0-9][a-z0-9-]{2,63}$/u;
const BOOK_ID_PATTERN = /^[a-z][a-z0-9-]{2,62}[a-z0-9]$/u;
const BOOK_NAME_PATTERN = /^(publishers\/[a-z0-9][a-z0-9-]{2,63})\/books\/([a-z][a-z0-9-]{2,62}[a-z0-9])$/u;
const DEFAULT_TTL_MS = 30 * 60 * 1000;
const DEFAULT_MAX_LIBRARIES = 500;
const DEFAULT_MAX_BOOKS = 20;
const UPDATABLE_BOOK_PATHS = ["display_name", "note"] as const;
type UpdatableBookPath = (typeof UPDATABLE_BOOK_PATHS)[number];

interface LibraryState {
  books: Map<string, Book>;
  expiresAt: number;
  touchedAt: number;
}

export interface LibraryServiceOptions {
  maxBooks?: number;
  maxLibraries?: number;
  now?: () => number;
  ttlMs?: number;
}

function fieldError(field: string, description: string): ConnectError {
  return new ConnectError("Review the highlighted fields.", Code.InvalidArgument, undefined, [
    {
      desc: BadRequestSchema,
      value: { fieldViolations: [{ description, field }] },
    },
  ]);
}

function connectError(code: Code, message: string): ConnectError {
  return new ConnectError(message, code);
}

function parentFromName(name: string): string {
  const match = BOOK_NAME_PATTERN.exec(name);
  if (!match?.[1]) {
    throw fieldError("name", "Enter a book name such as publishers/my-library/books/my-book.");
  }
  return match[1];
}

function validateParent(parent: string): void {
  if (!PARENT_PATTERN.test(parent)) {
    throw fieldError("parent", "Enter a publisher name such as publishers/my-library.");
  }
}

function validateBookId(bookId: string): void {
  if (!BOOK_ID_PATTERN.test(bookId)) {
    throw fieldError("book_id", "Use 4–64 lowercase letters, numbers, or hyphens, starting with a letter.");
  }
}

function isUpdatableBookPath(path: string): path is UpdatableBookPath {
  return UPDATABLE_BOOK_PATHS.some((candidate) => candidate === path);
}

function populatedUpdatableBookPaths(book: Book): UpdatableBookPath[] {
  const paths: UpdatableBookPath[] = [];
  if (book.displayName !== "") {
    paths.push("display_name");
  }
  if (book.note !== undefined) {
    paths.push("note");
  }
  return paths;
}

export function createLibraryService({
  maxBooks = DEFAULT_MAX_BOOKS,
  maxLibraries = DEFAULT_MAX_LIBRARIES,
  now = Date.now,
  ttlMs = DEFAULT_TTL_MS,
}: LibraryServiceOptions = {}) {
  const libraries = new Map<string, LibraryState>();
  let version = 0;

  function nextEtag(): string {
    version += 1;
    return `v${version}`;
  }

  function makeBook(parent: string, bookId: string, displayName: string, isbn: string, note?: string) {
    const timestamp = timestampFromDate(new Date(now()));
    return create(BookSchema, {
      createTime: timestamp,
      displayName,
      etag: nextEtag(),
      isbn,
      name: `${parent}/books/${bookId}`,
      note,
      state: BookState.ACTIVE,
      uid: crypto.randomUUID(),
      updateTime: timestamp,
    });
  }

  function pruneExpired(): void {
    const currentTime = now();
    for (const [parent, library] of libraries) {
      if (library.expiresAt <= currentTime) {
        libraries.delete(parent);
        continue;
      }
      for (const [name, book] of library.books) {
        if (book.state === BookState.DELETED && book.purgeTime && timestampMs(book.purgeTime) <= currentTime) {
          library.books.delete(name);
        }
      }
    }
  }

  function seedLibrary(parent: string): LibraryState {
    const first = makeBook(
      parent,
      "designing-data-intensive-applications",
      "Designing Data-Intensive Applications",
      "9781449373320",
      "Reliable data systems and the trade-offs behind them."
    );
    const second = makeBook(
      parent,
      "domain-driven-design",
      "Domain-Driven Design",
      "9780321125217",
      "A shared language for complex software."
    );
    const currentTime = now();
    return {
      books: new Map([
        [first.name, first],
        [second.name, second],
      ]),
      expiresAt: currentTime + ttlMs,
      touchedAt: currentTime,
    };
  }

  function getLibrary(parent: string): LibraryState {
    validateParent(parent);
    pruneExpired();
    let library = libraries.get(parent);
    if (!library) {
      if (libraries.size >= maxLibraries) {
        const oldest = [...libraries.entries()].sort(([, left], [, right]) => left.touchedAt - right.touchedAt)[0]?.[0];
        if (oldest) {
          libraries.delete(oldest);
        }
      }
      library = seedLibrary(parent);
      libraries.set(parent, library);
    }
    const currentTime = now();
    library.touchedAt = currentTime;
    library.expiresAt = currentTime + ttlMs;
    return library;
  }

  function findBook(name: string) {
    const library = getLibrary(parentFromName(name));
    const book = library.books.get(name);
    if (!book) {
      throw connectError(Code.NotFound, `Book ${name} was not found.`);
    }
    return { book, library };
  }

  return {
    createBook(request) {
      validateParent(request.parent);
      validateBookId(request.bookId);
      if (!request.book) {
        throw fieldError("book", "Enter the book to create.");
      }
      if (!request.book.displayName.trim()) {
        throw fieldError("book.display_name", "Enter a book title.");
      }
      const library = getLibrary(request.parent);
      const name = `${request.parent}/books/${request.bookId}`;
      if (library.books.has(name)) {
        throw connectError(Code.AlreadyExists, `Book ${name} already exists.`);
      }
      if (library.books.size >= maxBooks) {
        throw connectError(Code.ResourceExhausted, "This temporary library has reached its book limit.");
      }
      const book = makeBook(
        request.parent,
        request.bookId,
        request.book.displayName,
        request.book.isbn,
        request.book.note
      );
      if (!request.validateOnly) {
        library.books.set(name, book);
      }
      return clone(BookSchema, book);
    },

    deleteBook(request) {
      const { book, library } = findBook(request.name);
      if (book.state === BookState.DELETED) {
        if (request.allowMissing) {
          return clone(BookSchema, book);
        }
        throw connectError(Code.NotFound, `Book ${request.name} was deleted.`);
      }
      if (request.etag && request.etag !== book.etag) {
        throw connectError(Code.Aborted, "This book changed. Refresh it before deleting.");
      }
      const deletionTime = timestampFromDate(new Date(now()));
      const deleted = clone(BookSchema, book);
      deleted.deleteTime = deletionTime;
      deleted.etag = nextEtag();
      deleted.purgeTime = timestampFromDate(new Date(now() + ttlMs));
      deleted.state = BookState.DELETED;
      deleted.updateTime = deletionTime;
      if (!request.validateOnly) {
        library.books.set(request.name, deleted);
      }
      return clone(BookSchema, deleted);
    },

    expungeBook(request) {
      const { library } = findBook(request.name);
      library.books.delete(request.name);
      return create(EmptySchema);
    },

    getBook(request) {
      return clone(BookSchema, findBook(request.name).book);
    },

    listBooks(request) {
      const library = getLibrary(request.parent);
      const filter = request.filter.trim().toLowerCase();
      const books = [...library.books.values()]
        .filter(
          (book) =>
            (request.showDeleted || book.state !== BookState.DELETED) &&
            (!filter || book.displayName.toLowerCase().includes(filter) || book.isbn.includes(filter))
        )
        .map((book) => clone(BookSchema, book));
      return { books };
    },

    undeleteBook(request) {
      const { book, library } = findBook(request.name);
      if (book.state !== BookState.DELETED) {
        throw connectError(Code.AlreadyExists, `Book ${request.name} is not deleted.`);
      }
      const restored = clone(BookSchema, book);
      restored.deleteTime = undefined;
      restored.etag = nextEtag();
      restored.purgeTime = undefined;
      restored.state = BookState.ACTIVE;
      restored.updateTime = timestampFromDate(new Date(now()));
      library.books.set(request.name, restored);
      return clone(BookSchema, restored);
    },

    updateBook(request) {
      if (!request.book) {
        throw fieldError("book", "Enter the book to update.");
      }
      const { book: current, library } = findBook(request.book.name);
      if (current.state === BookState.DELETED) {
        throw connectError(Code.FailedPrecondition, "Restore this book before updating it.");
      }
      const requestedPaths = request.updateMask?.paths;
      let paths: string[] = populatedUpdatableBookPaths(request.book);
      if (request.updateMask) {
        paths = requestedPaths?.includes("*") ? [...UPDATABLE_BOOK_PATHS] : (requestedPaths ?? []);
      }
      const normalizedPaths = paths.map((path) => (path === "displayName" ? "display_name" : path));
      const unsupported = normalizedPaths.filter((path) => !isUpdatableBookPath(path));
      if (unsupported.length > 0) {
        throw fieldError("update_mask", `These fields cannot be updated: ${unsupported.join(", ")}.`);
      }
      const updatablePaths = normalizedPaths.filter(isUpdatableBookPath);
      if (!request.book.etag || request.book.etag !== current.etag) {
        throw connectError(Code.FailedPrecondition, "This book changed. Refresh it before saving.");
      }
      if (updatablePaths.length === 0) {
        return clone(BookSchema, current);
      }
      const next = clone(BookSchema, current);
      for (const path of updatablePaths) {
        switch (path) {
          case "display_name":
            if (!request.book.displayName.trim()) {
              throw fieldError("book.display_name", "Enter a book title.");
            }
            next.displayName = request.book.displayName;
            break;
          case "note":
            next.note = request.book.note;
            break;
          default:
            throw new TypeError(`Unsupported update path: ${path satisfies never}`);
        }
      }
      next.etag = nextEtag();
      next.updateTime = timestampFromDate(new Date(now()));
      if (!request.validateOnly) {
        library.books.set(next.name, next);
      }
      return clone(BookSchema, next);
    },
  } satisfies ServiceImpl<typeof LibraryService>;
}

