    (google.api.field_behavior) = REQUIRED,
    (google.api.field_behavior) = IMMUTABLE,
    (buf.validate.field).required = true,
    (buf.validate.field).string.pattern = "^[0-9]{13}$",
    (buf.validate.field).cel = {
      id: "book.isbn13_check_digit"
      message: "ISBN must have a valid ISBN-13 check digit."
      expression: "!this.matches('^[0-9]{13}$') || (int(this.substring(0, 1)) + int(this.substring(1, 2)) * 3 + int(this.substring(2, 3)) + int(this.substring(3, 4)) * 3 + int(this.substring(4, 5)) + int(this.substring(5, 6)) * 3 + int(this.substring(6, 7)) + int(this.substring(7, 8)) * 3 + int(this.substring(8, 9)) + int(this.substring(9, 10)) * 3 + int(this.substring(10, 11)) + int(this.substring(11, 12)) * 3 + int(this.substring(12, 13))) % 10 == 0"
    }
  ];
  // An optional token consumed while creating or updating the book.
  string input_token = 8 [
    (google.api.field_behavior) = OPTIONAL,
    (google.api.field_behavior) = INPUT_ONLY
  ];
  // An optional note about the book.
